CREATE FUNCTION public.check_invoice_claim_encounter() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE
  claim_encounter bigint;
BEGIN
  IF NEW.claim_id IS NOT NULL AND NEW.encounter_id IS NOT NULL THEN
    SELECT encounter_id INTO claim_encounter FROM public.claims
    WHERE claim_id = NEW.claim_id AND hospital_id = NEW.hospital_id
      AND branch_id = NEW.branch_id AND patient_id = NEW.patient_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Invoice claim ownership is invalid' USING ERRCODE = '23503';
    END IF;
    IF claim_encounter IS DISTINCT FROM NEW.encounter_id THEN
      RAISE EXCEPTION 'Invoice and claim encounters must agree' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER invoices_claim_encounter_consistent
AFTER INSERT OR UPDATE ON public.invoices DEFERRABLE INITIALLY IMMEDIATE
FOR EACH ROW EXECUTE FUNCTION public.check_invoice_claim_encounter();
--> statement-breakpoint
CREATE FUNCTION public.check_claim_invoice_encounter() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  IF NEW.encounter_id IS DISTINCT FROM OLD.encounter_id AND EXISTS (
    SELECT 1 FROM public.invoices i
    WHERE i.claim_id = NEW.claim_id AND i.hospital_id = NEW.hospital_id
      AND i.branch_id = NEW.branch_id AND i.encounter_id IS NOT NULL
      AND i.encounter_id IS DISTINCT FROM NEW.encounter_id
  ) THEN
    RAISE EXCEPTION 'Claim encounter change would invalidate an invoice' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER claims_invoice_encounter_consistent
AFTER UPDATE ON public.claims DEFERRABLE INITIALLY IMMEDIATE
FOR EACH ROW EXECUTE FUNCTION public.check_claim_invoice_encounter();
--> statement-breakpoint
CREATE VIEW public.vw_claim_dashboard WITH (security_invoker = true) AS
SELECT c.hospital_id, c.branch_id, c.claim_id, c.claim_no, c.patient_id,
       CONCAT_WS(' ', p.first_name, p.middle_name, p.last_name) AS patient_name,
       ic.company_name AS insurance_company, t.tpa_name, pi.policy_number,
       c.claim_type, c.claim_stage, c.claim_status, c.estimated_amount,
       c.claimed_amount, c.approved_amount, c.patient_payable_amount,
       c.created_at, c.updated_at
FROM public.claims c
JOIN public.patients p ON p.patient_id = c.patient_id AND p.hospital_id = c.hospital_id
JOIN public.patient_insurance pi ON pi.patient_insurance_id = c.patient_insurance_id
     AND pi.patient_id = c.patient_id AND pi.hospital_id = c.hospital_id
JOIN public.insurance_policies pol ON pol.policy_id = pi.policy_id
JOIN public.insurance_companies ic ON ic.insurance_company_id = pol.insurance_company_id
LEFT JOIN public.tpas t ON t.tpa_id = pol.tpa_id;
--> statement-breakpoint
CREATE VIEW public.vw_patient_insurance WITH (security_invoker = true) AS
SELECT pi.hospital_id, pi.patient_insurance_id, pi.patient_id,
       CONCAT_WS(' ', p.first_name, p.middle_name, p.last_name) AS patient_name,
       ic.company_name, t.tpa_name, pol.plan_name, pol.policy_type,
       pi.policy_number, pi.member_id, pi.valid_from, pi.valid_to,
       pi.sum_insured, pi.verification_status
FROM public.patient_insurance pi
JOIN public.patients p ON p.patient_id = pi.patient_id AND p.hospital_id = pi.hospital_id
JOIN public.insurance_policies pol ON pol.policy_id = pi.policy_id
JOIN public.insurance_companies ic ON ic.insurance_company_id = pol.insurance_company_id
LEFT JOIN public.tpas t ON t.tpa_id = pol.tpa_id;
--> statement-breakpoint
CREATE VIEW public.vw_claim_status_summary WITH (security_invoker = true) AS
SELECT hospital_id, branch_id, claim_status, COUNT(*) AS total_claims,
       SUM(claimed_amount) AS claimed_amount, SUM(approved_amount) AS approved_amount,
       COUNT(*) FILTER (WHERE claimed_amount IS NULL) AS claimed_amount_unknown_count,
       COUNT(*) FILTER (WHERE approved_amount IS NULL) AS approved_amount_unknown_count
FROM public.claims GROUP BY hospital_id, branch_id, claim_status;
--> statement-breakpoint
CREATE VIEW public.vw_claim_type_summary WITH (security_invoker = true) AS
SELECT hospital_id, branch_id, claim_type, COUNT(*) AS total_claims,
       SUM(claimed_amount) AS claimed_amount, SUM(approved_amount) AS approved_amount,
       COUNT(*) FILTER (WHERE claimed_amount IS NULL) AS claimed_amount_unknown_count,
       COUNT(*) FILTER (WHERE approved_amount IS NULL) AS approved_amount_unknown_count
FROM public.claims GROUP BY hospital_id, branch_id, claim_type;
